    const mpModal = document.getElementById('missingPiecesModal');
    const ugcCache = {};
    let mpItems = [];
    let mpIndex = 0;

    function getInitials(name = '') {
      const parts = String(name).trim().split(/\s+/).filter(Boolean);
      if (!parts.length) return 'HE';
      return parts.slice(0, 2).map(p => p[0].toUpperCase()).join('');
    }

    async function fetchMissingPiecesMedia(nhleId) {
      const key = String(nhleId).trim();
      if (!key) return { items: [], source: 'ugcapi.historicengland.org.uk' };
      if (ugcCache[key]) return ugcCache[key];

      // Tier 1: Same-origin static shard built into the repo (no CORS on GitHub Pages)
      try {
        const localRes = await fetch(`./api/ugc/${encodeURIComponent(key)}.json`);
        if (localRes.ok) {
          const localData = await localRes.json();
          if (Array.isArray(localData) && localData.length > 0) {
            ugcCache[key] = { items: localData, source: `./api/ugc/${key}.json` };
            return ugcCache[key];
          }
        }
      } catch (e) {}

      // Tier 2: Live Historic England UGC API (works locally or if CORS permits for unsharded IDs)
      try {
        const res = await fetch(`https://ugcapi.historicengland.org.uk/api/media/${encodeURIComponent(key)}`);
        if (res.ok) {
          const data = await res.json();
          if (Array.isArray(data) && data.length > 0) {
            ugcCache[key] = { items: data, source: `ugcapi.historicengland.org.uk/api/media/${key}` };
            return ugcCache[key];
          }
        }
      } catch (e) {}

      // Tier 3: Bundled sample data for offline/local testing
      if (SAMPLE_MISSING_PIECES_BY_ID[key]) {
        ugcCache[key] = { items: SAMPLE_MISSING_PIECES_BY_ID[key], source: `Sample JSON (NHLE #${key})` };
        return ugcCache[key];
      }

      ugcCache[key] = { items: [], source: `ugcapi.historicengland.org.uk/api/media/${key}` };
      return ugcCache[key];
    }

    function updateMpBadge(count) {
      const button = document.getElementById('openMissingPiecesBtn');
      const badge = document.getElementById('mpBadgeCount');
      if (!button || !badge) return;
      const hasMedia = Number.isFinite(count) && count > 0;
      button.classList.toggle('hidden', !hasMedia);
      if (hasMedia) {
        badge.textContent = String(count);
        badge.classList.remove('hidden');
      } else {
        badge.classList.add('hidden');
      }
    }

    function renderMpSlide(idx) {
      if (!mpItems.length) return;
      mpIndex = ((idx % mpItems.length) + mpItems.length) % mpItems.length;
      const item = mpItems[mpIndex];
      const comment = item.comment || {};
      const imgUrl = (item.url || item.blobStorageUrl || '').replace(/^http:\/\//i, 'https://');
      const contributor = comment.username || 'Anonymous Contributor';
      const note = [item.caption, item.description, comment.text]
        .map(s => (s || '').trim())
        .filter(Boolean)
        .join(' — ') || 'No caption or note provided.';
      const dateStr = comment.created
        ? new Date(comment.created).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
        : '';

      const stageImg = document.getElementById('mpStageImg');
      const stageFallback = document.getElementById('mpImgFallback');
      stageFallback.classList.add('hidden');
      stageImg.classList.remove('hidden');
      stageImg.onload = () => stageFallback.classList.add('hidden');
      stageImg.onerror = () => {
        stageImg.classList.add('hidden');
        stageFallback.classList.remove('hidden');
      };
      stageImg.src = imgUrl;
      stageImg.alt = `${note} — ${contributor}`;

      document.getElementById('mpCounter').textContent = `${mpIndex + 1} / ${mpItems.length}`;
      document.getElementById('mpDirectFileLink').href = imgUrl || MISSING_PIECES_PROJECT_URL;

      const avatarImg = document.getElementById('mpAvatarImg');
      const avatarInitials = document.getElementById('mpAvatarInitials');
      avatarInitials.textContent = getInitials(contributor);
      avatarImg.classList.add('hidden');
      if (comment.userAvatarUrl) {
        avatarImg.onload = () => avatarImg.classList.remove('hidden');
        avatarImg.onerror = () => avatarImg.classList.add('hidden');
        avatarImg.src = comment.userAvatarUrl;
        avatarImg.alt = contributor;
      }

      document.getElementById('mpContributorName').textContent = contributor;
      document.getElementById('mpDateLabel').textContent = dateStr ? `• ${dateStr}` : '';
      document.getElementById('mpCaptionText').textContent = note;

      document.querySelectorAll('.mp-thumb-btn').forEach((btn, i) => {
        if (i === mpIndex) {
          btn.classList.add('ring-2', 'ring-rose-500', 'border-rose-500', 'opacity-100');
          btn.classList.remove('opacity-65', 'border-slate-700');
          btn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
        } else {
          btn.classList.remove('ring-2', 'ring-rose-500', 'border-rose-500', 'opacity-100');
          btn.classList.add('opacity-65', 'border-slate-700');
        }
      });
    }

    function renderMpFilmStrip() {
      const strip = document.getElementById('mpFilmStrip');
      strip.innerHTML = mpItems.map((item, i) => {
        const thumbUrl = (item.url || item.blobStorageUrl || '').replace(/^http:\/\//i, 'https://');
        const user = item.comment?.username || 'Contributor';
        return `
          <button
            type="button"
            data-mp-idx="${i}"
            class="mp-thumb-btn shrink-0 w-24 h-16 rounded-md overflow-hidden border border-slate-700 bg-slate-950 focus:outline-none transition-all opacity-65 hover:opacity-100 flex items-center justify-center"
            title="#${i + 1}: ${user}"
          >
            <img src="${thumbUrl}" alt="${user}" class="w-full h-full object-cover" loading="lazy" />
            <span style="display:none" class="text-[10px] font-mono text-slate-400">#${i + 1}</span>
          </button>
        `;
      }).join('');

      strip.querySelectorAll('.mp-thumb-btn').forEach(btn => {
        const img = btn.querySelector('img');
        img.addEventListener('error', () => {
          img.style.display = 'none';
          img.nextElementSibling.style.display = 'inline';
        });
        btn.addEventListener('click', () => renderMpSlide(Number(btn.dataset.mpIdx)));
      });
    }

    async function openMissingPiecesModal() {
      const doc = docsCache[activeId];
      const title = (doc?.identified_by || []).find(i => i.type === 'Name')?.content || doc?._label || `NHLE #${activeId}`;
      document.getElementById('mpModalTitle').textContent = `Missing Pieces — ${title}`;
      document.getElementById('mpSubtitle').textContent = `NHLE List Entry #${activeId}`;
      document.getElementById('mpProjectLink').href = MISSING_PIECES_PROJECT_URL;

      const { items, source } = await fetchMissingPiecesMedia(activeId);
      document.getElementById('mpSourceLabel').textContent = source;

      if (!items.length) {
        mpItems = [];
        document.getElementById('mpCounter').textContent = '0 / 0';
        document.getElementById('mpStageImg').src = '';
        document.getElementById('mpStageImg').classList.add('hidden');
        document.getElementById('mpImgFallback').classList.add('hidden');
        document.getElementById('mpContributorName').textContent = 'No crowdsourced images found';
        document.getElementById('mpDateLabel').textContent = '';
        document.getElementById('mpCaptionText').textContent = `No media items returned from ugcapi.historicengland.org.uk/api/media/${activeId}.`;
        document.getElementById('mpFilmStrip').innerHTML = '';
        mpModal.classList.remove('hidden');
        mpModal.classList.add('flex');
        return;
      }

      mpItems = items;
      renderMpFilmStrip();
      renderMpSlide(0);
      mpModal.classList.remove('hidden');
      mpModal.classList.add('flex');
    }

    function closeMissingPiecesModal() {
      mpModal.classList.add('hidden');
      mpModal.classList.remove('flex');
    }

    document.getElementById('openMissingPiecesBtn').addEventListener('click', openMissingPiecesModal);
    document.getElementById('closeMpModalBtn').addEventListener('click', closeMissingPiecesModal);
    document.getElementById('mpPrevBtn').addEventListener('click', () => renderMpSlide(mpIndex - 1));
    document.getElementById('mpNextBtn').addEventListener('click', () => renderMpSlide(mpIndex + 1));
    mpModal.addEventListener('click', (e) => {
      if (e.target === mpModal) closeMissingPiecesModal();
    });

    async function loadMissingPiecesForActive(id) {
      const { items } = await fetchMissingPiecesMedia(id);
      if (activeId === id) {
        updateMpBadge(items.length);
      }
    }

    document.addEventListener('keydown', (e) => {
      if (!mpModal.classList.contains('hidden')) {
        if (e.key === 'Escape') closeMissingPiecesModal();
        if (e.key === 'ArrowLeft') renderMpSlide(mpIndex - 1);
        if (e.key === 'ArrowRight') renderMpSlide(mpIndex + 1);
        return;
      }
      if (e.key === 'Escape') {
        if (!corpusModal.classList.contains('hidden')) closeCorpusModal();
        if (!descModal.classList.contains('hidden')) closeDescriptionModal();
      }
    });

